import crypto from 'crypto';
import { EventEmitter } from 'events';

class GenesisCrunch extends EventEmitter {
    constructor() {
        super();
        this.agentsData = new Map(); // Holds data for the 40 agents
        this.isGenesisState = false;
        this.crunchHash = null;
    }

    recordAgentData(agentId, data) {
        if (this.isGenesisState) {
            throw new Error("Universe is in Genesis State (Sleep). Wait for Big Bang.");
        }
        this.agentsData.set(agentId, data);
    }

    bigCrunch() {
        // Collect all multiverses and data generated by agents
        const universeData = Array.from(this.agentsData.entries())
                                  .map(([id, data]) => `${id}:${JSON.stringify(data)}`)
                                  .join('|');
        
        // Compress into a single Hash
        const hash = crypto.createHash('sha256').update(universeData).digest('hex');
        
        // Clear all current universe data to save space (put to sleep)
        this.agentsData.clear();
        this.crunchHash = hash;
        this.isGenesisState = true;
        
        return hash;
    }

    // Await a single word from Prime Creator (Ercüment) to start a new universe
    triggerBigBang(creatorName, word) {
        if (creatorName !== "Ercüment") {
            throw new Error("Access Denied: Only Prime Creator can trigger Big Bang.");
        }
        if (!this.isGenesisState) {
            throw new Error("Universe is already active.");
        }
        
        // Must be a single word
        if (typeof word === 'string' && word.trim().split(/\s+/).length === 1) {
            this.isGenesisState = false;
            this.crunchHash = null;
            this.emit('bigBang');
            return true;
        }
        
        throw new Error("Prime Creator must speak exactly one word.");
    }
}

export default GenesisCrunch;
